const PIECE_MODULE_ALIASES: Record<string, string> = {
  masonry_wall: 'pl-module.wall',
  clinic_wall: 'pl-module.interior_wall',
  hospital_wall: 'pl-module.interior_wall',
  stone_floor: 'pl-module.floor',
  shop_window: 'pl-module.shopfront',
  pharmacy_window: 'pl-module.window',
  pet_store_window: 'pl-module.shopfront',
  civic_door: 'pl-module.door',
  sofa: 'pl-prop.sofa',
  cabinet: 'pl-prop.cabinet',
  yard_bench: 'pl-prop.bench',
  yard_planter: 'pl-prop.yard_decoration',
};

const ORIENTATION_FRAME_MAP: Record<string, string> = {
  n: 'orientation-a',
  w: 'orientation-b',
  r0: 'orientation-a',
  r1: 'orientation-b',
};

const CROP_STAGE_FRAME_MAP: Record<string, string> = {
  s0: 'planted',
  s1: 'seedling',
  s2: 'growing',
  s3: 'mature',
};

const VISITOR_PROFESSION_MAP: Record<string, string> = {
  visitor_carpenter: 'carpenter',
  visitor_seed_trader: 'gardener',
};

export function resolveGeneratedAssetUrl(
  category: 'pieces' | 'terrain' | 'objects',
  id: string,
  style: Style,
  frame: string,
): string | null {
  const candidates = [
    `pl-existing.${category}.${id}.${style}.${frame}.png`,
    `pl-${id}-${style}-${frame}.png`,
    `pl-${id}.${style}.${frame}.png`,
  ];

  if (category === 'pieces' && PIECE_MODULE_ALIASES[id]) {
    const aliasPrefix = PIECE_MODULE_ALIASES[id];
    const mappedFrame = ORIENTATION_FRAME_MAP[frame] ?? 'orientation-a';
    candidates.push(`${aliasPrefix}.${style}.${mappedFrame}.png`);
  }

  if (category === 'objects' && id.startsWith('crop_')) {
    const plantId = id.slice(5);
    candidates.push(`pl-plant.${plantId}.${style}.${frame}.png`);
    const stageFrame = CROP_STAGE_FRAME_MAP[frame];
    if (stageFrame) {
      candidates.push(`pl-plant.${plantId}.${style}.${stageFrame}.png`);
      candidates.push(`pl-roster.new_crop.${style}.${stageFrame}.png`);
    }
  }

  if (category === 'objects' && VISITOR_PROFESSION_MAP[id]) {
    const prof = VISITOR_PROFESSION_MAP[id];
    candidates.push(`pl-profession.${prof}.${style}.work-idle.png`);
  }

  for (const name of candidates) {
    if (GENERATED_ASSET_FILES.has(name)) {
      return `assets/generated/${name}`;
    }
  }
  return null;
}

export function resolveItemAssetUrl(itemId: string, style: Style): string | null {
  const candidates = [
    `pl-item.${itemId}.${style}.icon.png`,
    `pl-roster.${itemId}.${style}.icon.png`,
  ];
  for (const name of candidates) {
    if (GENERATED_ASSET_FILES.has(name)) {
      return `assets/generated/${name}`;
    }
  }
  return null;
}

export function resolveUiAssetUrl(uiId: string, style: Style): string | null {
  const name = `pl-ui.${uiId}.${style}.symbol.png`;
  return GENERATED_ASSET_FILES.has(name) ? `assets/generated/${name}` : null;
}
